package com.cloudticket.comment.persistence.mapper;
import com.baomidou.mybatisplus.core.mapper.BaseMapper; import com.baomidou.mybatisplus.extension.plugins.pagination.Page; import com.cloudticket.comment.persistence.entity.CommentEntity; import org.apache.ibatis.annotations.Param; import org.apache.ibatis.annotations.Select; import org.apache.ibatis.annotations.Update;
public interface CommentMapper extends BaseMapper<CommentEntity> { @Select("SELECT * FROM comment WHERE activity_id=#{activityId} AND status='VISIBLE' AND parent_id IS NULL ORDER BY created_at DESC") Page<CommentEntity> selectVisible(Page<CommentEntity> page,@Param("activityId") String activityId); @Select("SELECT * FROM comment WHERE parent_id=#{parentId} AND status='VISIBLE' ORDER BY created_at ASC") java.util.List<CommentEntity> selectReplies(@Param("parentId") String parentId); @Select("SELECT * FROM comment WHERE (#{activityId}='' OR activity_id=#{activityId}) AND (#{status}='' OR status=#{status}) ORDER BY created_at DESC") Page<CommentEntity> selectAdmin(Page<CommentEntity> page,@Param("activityId") String activityId,@Param("status") String status); @Update("UPDATE comment SET reply_count=reply_count+1 WHERE id=#{id}") int incrementReply(@Param("id") String id); @Update("UPDATE comment SET status=#{status} WHERE id=#{id}") int changeStatus(@Param("id") String id,@Param("status") String status); @Update("UPDATE comment SET like_count=#{count} WHERE id=#{id}") int updateLikeCount(@Param("id") String id,@Param("count") int count); }
